/* 자동 생성 — scripts/build-gov24.mjs. 손으로 고치지 않는다.
 *
 * 행정안전부 「대한민국 공공서비스(혜택) 정보」(보조금24)에서 우리 수록 사업과
 * **확실히 같은 것**만 골라 담았다(매칭 규칙은 그 스크립트 머리말).
 * 값은 원문 그대로이고, 화면에는 출처와 확인일을 함께 적는다.
 */
export type Gov24Row = {
  /** 우리 수록 사업 id */
  id: string;
  /** 보조금24 서비스ID */
  gid: string;
  gname: string;
  gorg: string;
  /** 이름 유사도(0~1). 0.75 미만은 아예 싣지 않는다. */
  score: number;
  docs: string | null;
  officialDocs: string | null;
  laws: string | null;
  localLaws: string | null;
  onlineUrl: string | null;
  deadline: string | null;
};

/** 보조금24 원본을 받아 대조한 날. */
export const GOV24_CHECKED = "2026-09-16";

