 "WLF00000044": {
  "id": "WLF00000044",
  "gid": "149200000009",
  "gname": "생활안정자금(융자)",
  "gorg": "고용노동부",
  "score": 1,
  "docs": "1. 공통: 가족관계증명서(융자 대상자가 노동자 본인의 직계 존·비속이 아닌 경우), 건강보험증 또는 의료급여증 사본(융자 대상자가 노동자 본인의 건강보험증에 피부양자로 등록되어 있지 않은 경우), 소득증빙자료(행정정보 공동이용으로 확인이 되지 않는 경우, 직전년도에 현 소속 사업장에서의 근무 기간이 3개월 미만이거나 직전년도와 전전년도 소득 확인이 불가능한 경우에는 융자신청일 이전 3개월분 급여명세서), 근로계약서(비정규직 노동자), 위수탁·도급·노무 제공 등 계약서(특수형태근로종사자), 임대차계약서(특수형태근로종사자 및 1인 자영업자)\r\n\r\n2. 의료비: 요양기관 및 의료기관에 치료 후 납부하거나 납하여야 할 비용(진료비 및 약제비 등) 영수증 또는 청구서, 산후조리원 이용 비용 증명서(계산서 또는 영수증), 요양시설 이용 비용 증명서(계산서 또는 영수증)\r\n\r\n3. 장례비: 사망진단서 또는 사망확인서(사망 사실이 가족관계증명서에 기재되지 않은 경우)\r\n\r\n4. 혼례비: 혼인관계증명서(융자 대상자가 자녀인 경우)\r\n\r\n5. 소액생계비: 소득감소 사실 확인서(별지 제4호 서식), 융자 대상 월 및 직전월 급여명세서(또는 수당, 수수료 지급명세서 등 소득감소를 확인할 수 있는 서류), 휴업·휴직 확인서, 재직증명서(휴직 기간 포함) 등 소득감소 사유를 확인할 수 있는 서류",
  "officialDocs": "ㅇ 공통: 소득증빙자료(소득금액증명, 부가가치세과세표준증명, 부가가치세면세사업자수입금액증명, 주민등록표 등·초본(융자 대상자가 노동자 본인이 아닌 경우), 건강보험자격확인서(융자 대상자가 노동자 본인이 아닌 경우), 사업자등록증명(필요한 경우), 북한이탈주민등록확인서(북한이탈주민)",
  "laws": "근로복지기본법(제19조)||근로복지기본법(제91조, 제2항)",
  "localLaws": null,
  "onlineUrl": "https://welfare.comwel.or.kr",
  "deadline": "상시신청"
 },
