 "WLF00006181": {
  "id": "WLF00006181",
  "gid": "611000019624",
  "gname": "자녀출산 무주택가구 주거비 지원",
  "gorg": "서울특별시",
  "score": 1,
  "docs": "<필수 제출서류>\r\n① 신청자·배우자의 가족관계증명서 (배우자 있는 경우, 신청인·배우자 모두 제출)\r\n② 신청자·배우자의 청약홈 주택소유현황 (배우자 있는 경우, 신청인·배우자 모두 제출)\r\n③ 확정일자 날인된 임대차계약서 전체 사본(확정일자 미날인된 경우 주택임대차계약신고필증 추가 제출)\r\n④ 신용정보조회서 (임대차계약자 기준, ※보증금 대출 여부 확인을 위해 제출)\r\n   ※ 한국신용정보원 본인신용정보 열람서비스(https://www.credit4u.or.kr) → 신용정보조회서 발급\r\n\r\n<※해당시※ 필수 제출서류>\r\n- 금융거래확인서(임대차계약자 기준, ※보증금 대출이 있는 가구만, 대출 은행의 금융거래확인서 제출)\r\n※ 보증금 대출 없음으로 신청한 가구에서, 보증금 대출이 확인될 경우 금융거래확인서 제출 필요\r\n- 개인정보활용동의서(배우자 또는 추가 세대원이 있는 경우 필수 제출)\r\n- 다문화가족인 경우 : 외국인등록증 앞, 뒷면 사본\r\n- 입양아인 경우 : 입양관계증명서, 친양자입양관계증명서\r\n\r\n ※주민등록 등‧초본, 지방세세목별과세증명서(재산세), 주거급여 수급정보 등은 행정정보공동이용 조회 예정",
  "officialDocs": "ㅇ 주민등록표 등초본\r\n ㅇ소득금액증명원\r\n ㅇ주거급여 수급정보\r\n ㅇ지방세 세목별 과세 증명서",
  "laws": null,
  "localLaws": "서울특별시 출산 및 양육지원에 관한 조례(제5조, 제1항)",
  "onlineUrl": "https://umppa.seoul.go.kr/hmpg/sprt/bzin/bzmgComtDetail.do?biz_mng_no=197DA8F773AAE8DCE063A6022162FF67",
  "deadline": "'26.7.1.~12.31.(하반기) ※'27년 모집은 별도 공고 예정"
 },
