 "WLF00004976": {
  "id": "WLF00004976",
  "gid": "627000000113",
  "gname": "대구광역시 다자녀가정 고등학교 입학축하금 지원",
  "gorg": "대구광역시",
  "score": 0.86,
  "docs": "신청서 작성, 고등학교 재학증명서, 주민등록 등본, 가족관계증명서(주소가 다른 자녀가 있는 경우로 신청학생의 출생순위 확인이 되지 않는 경우에 제출 )\r\n\r\n**온라인 접수시 주의사항_  노트북, 데스크탑 이용/휴대전화는 기기 사양 다양성으로 불편함 있음\r\n  신청서 작성시 반드시 ① 신청자(부또는 모) 명의로 로그인하고 ② 신청자 연락처(휴대전화)  ③학생의 출생순위(2,3,4,5등 등)\r\n ④재학증명서_필수, 주소가 다른 자녀 있는 경우 또는 신청학생의 출생순위 확인되지 않을 경우에는 가족관계증명서를 첨부 합니다.\r\n ⑤ 대구로페이카드 사본 첨부(사진파일 또는 캡쳐 등) 첨부 \r\n\r\n  < 고등학교 재학증명서 발급시 유의> _ 첨부파일은 사진파일도 가능함\r\n  - 정부24에서 발급시 학생이름으로 로그인 - 재학증명서는 업로드해서 바탕화면에 별도 저장\r\n  - 가족관계 증명서는 신청자와 자녀의 관계가 보여지도록 발급하여 신청서에 첨부 할 것\r\n  - 대구로페이 카드는 신청자(부또는 모)의 실명이 등록된 카드를 신청서에 등록함_(은행(iM뱅크) 방문 발급) 또는 모바일카드 모두 가능함\r\n   **(대구로페이 실물카드의 실명등록 방법)신분증 지참하여 iM뱅크 영업점 방문 등록 또는 휴대전화기 iM#앱에서 실물카드 등록\r\n\r\n  <휴대전화에 대구로페이 모바일카드 발급하는 방법>\r\n*(카드발급)휴대전화 play스토어>iM샵(#)>대구로pay>모바일카드 발급\r\n*(카드번호 확인) iM샵(#)>대구로pay>카드상세>카드정보확인>간편비빌번호 입력>카드번호확인\r\n*(문의) ☎1588-5050, 1566-5050, (주)iM뱅크 영업점 방문\r\n-> 대구로 모바일 카드번호의 순서는 (16자리) 9460-3100-****-****이며 모두 표기하여 작성합니다.",
  "officialDocs": "주민등록등본(초본)_행정정보 이용 담당공무원 확인",
  "laws": null,
  "localLaws": "대구광역시 출산장려 및 양육지원에 관한 조례(제9조)",
  "onlineUrl": null,
  "deadline": "2026.8.24.(월)9:00~9.30.(수)18:00(온라인 24:00)"
 },
