  "docs": "① 지원신청서\r\n② 개인정보 수집이용 및 제3자 제공 동의서\r\n③ 주민등록등본\r\n④ 가족관계증명서\r\n⑤ 본인신용정보조회서\r\n⑥ 임대차계약서 사본\r\n⑦ 주택임대차 계약신고필증\r\n⑧ 신분증 및 통장 사본\r\n⑨ 금융거래확인서\r\n⑩ 지방세 세목별 미과세증명서(전국/취득세(부동산), 재산세(건축물, 주택))\r\n※발급 제출 서류의 경우 공고일 이후 발급본만 인정되며, 필요시 추가로 자료 보완 요청을 할 수 있음.",
