  "gorg": "전남광주통합특별시 담양군",
  "score": 0.9,
  "docs": "○ 필수 : 신분증 \r\n\r\n○ 신청인 제출서류 \r\n    - 사회보장급여(사회서비스이용권) 신청서\r\n    - (필요 시) 가족관계증명서(부모 주소지가 다를 경우, 출생순위 확인이 어려운 경우, 가족관계 확인이 어려운 경우 등 추가제출)\r\n    - (필요 시) 휴직증명서 1부(신청일 기준, 휴직기간이 1개월 이상일 경우 추가제출)\r\n                  유급휴직인 경우, 최근 월분 급여명세서 추가제출\r\n\r\n○ 공무원 확인 가능 서류 \r\n    - 주민등록등본 \r\n    - 건강보험 자격확인서 \r\n    - 건강·장기요양 보험료납부확인서\r\n     ※행정정보 공동이용 사전동의 필요",
