 "WLF00005320": {
  "id": "WLF00005320",
  "gid": "569000000379",
  "gname": "세종시 청년 주택임차보증금 이자지원",
  "gorg": "세종특별자치시",
  "score": 0.83,
  "docs": "1. 공통서류\r\n\r\n  -  가족관계증명서 : 상세, 주민등록번호 뒷번호 포함 제출(본인, 배우자, 부, 모)\r\n\r\n  -  임차지 건축물대장 : 신규전세계약자  (발급처 정부24)\r\n\r\n2. 신청유형별 추가서류\r\n\r\n  1) 대학(원)생, 취업준비생\r\n\r\n     - 자격확인서류 : 재학 ·휴학·졸업예정증명서  ※ 세종시 거주자는 생략 가능\r\n\r\n     - 소득관련서류 : 사실증명원(소득이 없는 경우), 소득금액증명원, 원천징수영수증 중 한가지 제출(본인, 부모님)\r\n\r\n   2) 직장인(취·창업자)\r\n\r\n      - 자격확인서류 : 근로자의 경우 \"재직증명서\" 또는 \"건강보험자격득실확인서\", 사업자의 경우 \"사업자등록증\" 또는 \"사업자등록증명\"\r\n\r\n      - 소득관련서류(한가지 제출)\r\n\r\n        (1) 근로자 : 소득금액증명원, 원천징수영수증, 갑종근로소득금액증명서, 근로계약서, 급여명세서 등\r\n\r\n        (2) 자영업자 : 소득금액증명원, 사업소득원천징수영수증\r\n\r\n        (3)프리랜서 : 자영업자 준함(FAQ 참고)\r\n\r\n   3) 청년 신혼부부\r\n\r\n      - 자격확인서류 : 1), 2) 자격확인서류 참고\r\n\r\n      - 혼인관계증명서\r\n\r\n      -  소득관련서류 : 1), 2) 소득관련서류 참고\r\n\r\n      - 배우자의 개인정보 수집·이용 및 제3자 제공동의서, 가족관계증명서(상세, 주민번호 전체표시)",
  "officialDocs": null,
  "laws": "청년기본법(제20조)",
  "localLaws": null,
  "onlineUrl": null,
  "deadline": "금년 접수 마감"
 },
